def transform(grid):
    g = np.array(grid).copy()
    bg = background(g)
    H, W = g.shape
    seeds = [(y, x) for y in range(H) for x in range(W) if g[y, x] == 2]
    for (y, x) in seeds:
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                if dy == 0 and dx == 0:
                    continue
                yy, xx = y + dy, x + dx
                if 0 <= yy < H and 0 <= xx < W and g[yy, xx] == bg:
                    g[yy, xx] = 1
        emit(g, f"Surround the red cell at ({y},{x}) with a ring of 1s on its background neighbours.")
    emit(g, "All red cells are ringed; other colours stay unchanged.")
    return g
